        { step: "⑤ 海湾原油已绕道恢复", text: "9月最后一周七天里有四天出口超战前；Kpler 口径通行量为战前的76%。" },
        { step: "⑥ 胡塞战线扩大", text: "胡塞称袭击利雅得机场与拉比格阿美炼厂（沙特未证实）；沙特支持部队向曼德海峡推进。" },
        { step: "⑦ 官方确认外交渠道在运作", text: "巴加埃确认美方方案经卡塔尔转达；10月5日副外长确认美方看法正在国内审议。" },
        { step: "⑧ 三高层同日硬化口径", text: "10月6日总统称谈判「毫无意义」、议长重申七条件、外长称无军事解决方案。" },
        { step: "⑨ 盘中被实物流定价、收盘被地缘定价", text: "布伦特盘中跌3.3%到98附近、收盘100.58（+0.26%）；同一天里定价权换手。" },
        { step: "⑩ 绕行机制本身受质疑", text: "沙特东西管道停运传闻72小时无官方澄清，「管道绕行」降级为待验证假设。" }
